/// Decode-then-encode by type name. Used only by the shared conformance runner.
pub fn conformance_round_trip(type_name: &str, value: &Value) -> Option<Result<Value, DecodeError>> {
    match type_name {
        "FileInput" => Some(decode_file_input(value, "$").map(|decoded| encode_file_input(&decoded))),
        "FileId" => Some(decode_file_id(value, "$").map(|decoded| encode_file_id(&decoded))),
        "FileStaleReason" => Some(decode_file_stale_reason(value, "$").map(|decoded| encode_file_stale_reason(&decoded))),
        "ReadFormat" => Some(decode_read_format(value, "$").map(|decoded| encode_read_format(&decoded))),
        "FileInfo" => Some(decode_file_info(value, "$").map(|decoded| encode_file_info(&decoded))),
        "FilesRequest" => Some(decode_files_request(value, "$").map(|decoded| encode_files_request(&decoded))),
        "FilesResult" => Some(decode_files_result(value, "$").map(|decoded| encode_files_result(&decoded))),
        "FilesFact" => Some(decode_files_fact(value, "$").map(|decoded| encode_files_fact(&decoded))),
        _ => None,
    }
}
